document.addEventListener('click',function(event){const button=event.target.closest('[data-professional-action]');if(!button)return;try{if(!window.prototypeSelectionBridge)throw new Error('工作台尚未完成初始化');window.prototypeSelectionBridge.openProfessional(button.dataset.professionalAction);}catch(error){$('inputNotice').textContent=error.message;$('inputNotice').style.color='#9d3028';}});
